import { roundCoordinate } from "./parse-map-url";

export type LocationSource = "map" | "search" | "link" | "geolocation" | "coordinates";

export interface LocationDetails {
  address: string;
  city: string;
  area: string;
  country: string;
  countryCode: string;
}

export interface PlaceSuggestion {
  id: string;
  name: string;
  subtitle: string;
  lat: number;
  lng: number;
  kind: string;
  details: LocationDetails;
}

export const EMPTY_DETAILS: LocationDetails = { address: "", city: "", area: "", country: "", countryCode: "" };

const CACHE_LIMIT = 100;

function remember<T>(cache: Map<string, T>, key: string, value: T) {
  cache.set(key, value);
  if (cache.size > CACHE_LIMIT) {
    const oldest = cache.keys().next().value;
    if (oldest !== undefined) cache.delete(oldest);
  }
}

function abortError() {
  return new DOMException("Aborted", "AbortError");
}

export function isAbortError(error: unknown): boolean {
  return error instanceof DOMException && error.name === "AbortError";
}

/* ── Reverse geocoding (OpenStreetMap Nominatim) ──────────────────────────────
 * Nominatim's usage policy allows at most 1 request per second, so requests are queued
 * and spaced, cached by rounded coordinates, and skipped when cancelled while waiting. */

const NOMINATIM_GAP_MS = 1100;
const reverseCache = new Map<string, LocationDetails>();
let nominatimQueue: Promise<unknown> = Promise.resolve();
let lastNominatimAt = 0;

function scheduleNominatim<T>(task: () => Promise<T>, signal?: AbortSignal): Promise<T> {
  const run = nominatimQueue.then(async () => {
    if (signal?.aborted) throw abortError();
    const wait = lastNominatimAt + NOMINATIM_GAP_MS - Date.now();
    if (wait > 0) await new Promise((resolve) => setTimeout(resolve, wait));
    if (signal?.aborted) throw abortError();
    lastNominatimAt = Date.now();
    return task();
  });
  nominatimQueue = run.catch(() => undefined);
  return run;
}

function shortAddress(displayName: string | undefined): string {
  return (displayName || "").split(",").slice(0, 3).map((p) => p.trim()).filter(Boolean).join(", ");
}

export async function reverseGeocode(
  lat: number,
  lng: number,
  options: { language?: string; signal?: AbortSignal } = {}
): Promise<LocationDetails> {
  const language = options.language === "ar" ? "ar,en" : "en,ar";
  const key = `${roundCoordinate(lat).toFixed(5)},${roundCoordinate(lng).toFixed(5)}|${language}`;
  const cached = reverseCache.get(key);
  if (cached) return cached;

  return scheduleNominatim(async () => {
    const url =
      `https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&zoom=18` +
      `&lat=${lat}&lon=${lng}&accept-language=${encodeURIComponent(language)}`;
    const res = await fetch(url, { signal: options.signal });
    if (!res.ok) throw new Error(`Reverse geocoding failed (${res.status})`);
    const data = await res.json();
    const a = data?.address || {};
    const details: LocationDetails = {
      address: shortAddress(data?.display_name),
      city: a.city || a.town || a.municipality || a.village || a.county || a.state || "",
      area: a.suburb || a.neighbourhood || a.quarter || a.city_district || a.district || a.residential || "",
      country: a.country || "",
      countryCode: (a.country_code || "").toUpperCase(),
    };
    remember(reverseCache, key, details);
    return details;
  }, options.signal);
}

/* ── Place search / autocomplete (Photon by komoot, OpenStreetMap data) ────────
 * Photon is built for search-as-you-type (unlike Nominatim). Callers debounce input,
 * pass an AbortSignal, and results are cached per query. */

const searchCache = new Map<string, PlaceSuggestion[]>();

const PHOTON_LANGUAGES = new Set(["en", "de", "fr", "it"]);

function photonDetails(p: Record<string, any>): LocationDetails {
  const street = [p.street, p.housenumber].filter(Boolean).join(" ");
  return {
    address: [p.name, street, p.district || p.locality].filter(Boolean).join(", "),
    city: p.city || p.county || p.state || "",
    area: p.district || p.locality || (p.type === "district" || p.type === "locality" ? p.name : "") || "",
    country: p.country || "",
    countryCode: (p.countrycode || "").toUpperCase(),
  };
}

export async function searchPlaces(
  query: string,
  options: { language?: string; near?: { lat: number; lng: number } | null; signal?: AbortSignal; limit?: number } = {}
): Promise<PlaceSuggestion[]> {
  const q = query.trim();
  if (q.length < 3) return [];
  const lang = options.language && PHOTON_LANGUAGES.has(options.language) ? options.language : "default";
  const near = options.near ? `${options.near.lat.toFixed(2)},${options.near.lng.toFixed(2)}` : "";
  const key = `${q.toLowerCase()}|${lang}|${near}`;
  const cached = searchCache.get(key);
  if (cached) return cached;

  const params = new URLSearchParams({ q, limit: String(options.limit ?? 6), lang });
  if (options.near) {
    params.set("lat", String(options.near.lat));
    params.set("lon", String(options.near.lng));
  }
  const res = await fetch(`https://photon.komoot.io/api/?${params.toString()}`, { signal: options.signal });
  if (!res.ok) throw new Error(`Place search failed (${res.status})`);
  const data = await res.json();

  const seen = new Set<string>();
  const suggestions: PlaceSuggestion[] = [];
  for (const feature of data?.features ?? []) {
    const [lng, lat] = feature?.geometry?.coordinates ?? [];
    const p = feature?.properties ?? {};
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) continue;
    const name = p.name || [p.street, p.housenumber].filter(Boolean).join(" ") || p.city || "";
    if (!name) continue;
    const subtitle = [p.district || p.locality, p.city, p.state, p.country]
      .filter((part, i, all) => part && part !== name && all.indexOf(part) === i)
      .join(", ");
    const dedupeKey = `${name}|${subtitle}`;
    if (seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);
    suggestions.push({
      id: `${p.osm_type || "x"}${p.osm_id || suggestions.length}`,
      name,
      subtitle,
      lat,
      lng,
      kind: p.osm_value || p.type || "",
      details: photonDetails(p),
    });
  }
  remember(searchCache, key, suggestions);
  return suggestions;
}

/* ── Google reverse geocoding (through the server; the key never reaches the browser) ── */

export async function googleReverseGeocode(
  lat: number,
  lng: number,
  options: { language?: string; signal?: AbortSignal } = {}
): Promise<LocationDetails | null> {
  const params = new URLSearchParams({ lat: String(lat), lng: String(lng), language: options.language === "ar" ? "ar" : "en" });
  const res = await fetch(`/api/geocode?${params.toString()}`, { signal: options.signal });
  if (!res.ok) return null;
  const data = await res.json().catch(() => null);
  return data?.details ?? null;
}

/** Google first (more precise city/area names), OpenStreetMap as fallback. Never throws except on abort. */
export async function lookupAddress(
  lat: number,
  lng: number,
  options: { language?: string; signal?: AbortSignal; preferGoogle?: boolean } = {}
): Promise<LocationDetails> {
  if (options.preferGoogle) {
    try {
      const google = await googleReverseGeocode(lat, lng, options);
      if (google && (google.city || google.address)) return google;
    } catch (error) {
      if (isAbortError(error)) throw error;
    }
  }
  try {
    return await reverseGeocode(lat, lng, options);
  } catch (error) {
    if (isAbortError(error)) throw error;
    return EMPTY_DETAILS;
  }
}
